# Plots.jl figures (headless GR). Every figure title states what is compared:
# NUTS assessment chains (held out) vs samples generated by the trained flow.

using Plots
using Random

const NUTS_COLOR = :black
const FLOW_COLOR = :crimson

function make_plots(cell_dir, results, history, assess::AbstractMatrix, gen::AbstractMatrix; title::AbstractString="")
    default(fontfamily="sans-serif", dpi=110)
    names = EFT_NAMES
    d = length(names)
    A = Float64.(assess); G = Float64.(gen)

    # train / validation NLL curves (fixed-weight, full-dataset, physical coordinates)
    ep = [h.epoch for h in history]
    p = plot(ep, [h.train_nll for h in history]; label="training chains NLL", lw=2, xlabel="epoch",
             ylabel="mean NLL (physical EFT marginal)", title="$title: full-data NLL curves", legend=:topright)
    plot!(p, ep, [h.validation_nll for h in history]; label="validation chains NLL", lw=2)
    hl = results["heldout"]
    hline!(p, [hl["validation_gaussian_nll"]]; ls=:dash, color=:gray, label="validation: train-fitted Gaussian")
    best = results["best_epoch"]
    isnothing(best) || vline!(p, [best]; ls=:dot, color=:green, label="best validation epoch")
    savefig(p, joinpath(cell_dir, "nll_curves.png"))

    # marginal densities
    ps = Any[]
    for i in 1:d
        q = stephist(A[i, :]; normalize=:pdf, color=NUTS_COLOR, lw=2, label=(i == 1 ? "NUTS assessment (held-out chains 14-16)" : ""), xlabel=names[i], yticks=false)
        stephist!(q, G[i, :]; normalize=:pdf, color=FLOW_COLOR, lw=2, label=(i == 1 ? "flow samples" : ""))
        push!(ps, q)
    end
    savefig(plot(ps...; layout=(2, 4), size=(1500, 700), plot_title="$title: EFT marginals, NUTS assessment vs flow", plot_titlefontsize=10,
                 left_margin=4Plots.mm, bottom_margin=4Plots.mm), joinpath(cell_dir, "marginals.png"))

    # pairwise triangle (lower triangle scatter, diagonal densities)
    rng = Random.Xoshiro(1)
    ia = randperm(rng, size(A, 2))[1:min(1500, size(A, 2))]
    ig = randperm(rng, size(G, 2))[1:min(1500, size(G, 2))]
    tri = Any[]
    for r in 1:d, c in 1:d
        if r == c
            q = stephist(A[r, :]; normalize=:pdf, color=NUTS_COLOR, lw=1.5, legend=false, yticks=false)
            stephist!(q, G[r, :]; normalize=:pdf, color=FLOW_COLOR, lw=1.5)
        elseif r > c
            q = scatter(A[c, ia], A[r, ia]; ms=1.2, alpha=0.35, color=NUTS_COLOR, markerstrokewidth=0, legend=false)
            scatter!(q, G[c, ig], G[r, ig]; ms=1.2, alpha=0.35, color=FLOW_COLOR, markerstrokewidth=0)
        else
            q = plot(; framestyle=:none, legend=false)
        end
        r == d && xlabel!(q, names[c]); c == 1 && r > 1 && ylabel!(q, names[r])
        r < d && plot!(q; xformatter=_ -> "")
        c > 1 && plot!(q; yformatter=_ -> "")
        push!(tri, q)
    end
    savefig(plot(tri...; layout=(d, d), size=(2000, 2000), plot_title="$title: NUTS assessment (black) vs flow samples (red), 1500 points each",
                 plot_titlefontsize=14, tickfontsize=6, guidefontsize=8, left_margin=7Plots.mm, bottom_margin=3Plots.mm),
            joinpath(cell_dir, "triangle.png"))

    # correlations
    Rn, Rf = cor(A; dims=2), cor(G; dims=2)
    hm(M, t) = heatmap(M; yflip=true, clims=(-1, 1), c=:balance, title=t, xticks=(1:d, names), yticks=(1:d, names), xrotation=45, titlefontsize=8, tickfontsize=6)
    savefig(plot(hm(Rn, "NUTS assessment"), hm(Rf, "flow samples"),
                 heatmap(Rf .- Rn; yflip=true, clims=(-0.5, 0.5), c=:balance, title="flow - NUTS", xticks=(1:d, names),
                         yticks=(1:d, names), xrotation=45, titlefontsize=8, tickfontsize=6);
                 layout=(1, 3), size=(1500, 450), plot_title="$title: correlations", plot_titlefontsize=10),
            joinpath(cell_dir, "correlations.png"))
    return nothing
end
